"""Skeleton YAML generated by `tool-enabler new` for a brand-new profile."""

from __future__ import annotations

_CLI_TEMPLATE = '''# Tool Profile for __NAME__ — generated by `tool-enabler new`.
# Fill in every TODO below, then run `tool-enabler validate`. Passing
# validation only means the YAML is well-formed, not that the TODOs are
# filled in — that part is on you.
#
# Full schema reference: profiles/README.md in the tool-enabler repo.
# docs/custom-tools.md walks through a complete worked example.

name: __NAME__
display_name: "TODO: human-readable name, e.g. My Internal CLI"
binary: __NAME__
homepage: ""                 # optional — a docs URL, or leave blank for a private/internal tool
category: ""                  # optional, free text, e.g. "internal-tooling"

detect:
  installed_check: "__NAME__ --version"   # TODO: a real, cheap, side-effect-free check
  auth_check: ""                           # TODO: a cheap command confirming auth works, or leave blank if there's no auth
  install_hint: "TODO: how to install this (a brew/npm command, an internal artifact URL, or who to ask for access)"
  auth_setup: "TODO: the actual fix if auth_check fails (a login command) — or an explanation if there isn't a login step"

when_to_use:
  - "TODO: a concrete task this tool covers"

prefer_over:
  - tool: "TODO: e.g. doing this by hand"
    reason: "TODO: why this tool is better for that"

capabilities:
  # Required: at least one entry. Write the command the way you want an
  # agent to actually run it — explicit flags for structured output, not a
  # bare human-oriented invocation.
  - task: "TODO: what this accomplishes"
    command: "__NAME__ TODO"
    notes: ""              # optional — a gotcha specific to this invocation
    example_output: ""     # optional — a realistic sample of the output shape
    read_only: true         # set to false for anything side-effecting (confirm-before-running)

output_parsing:                # optional — leave empty/remove if the tool has no structured output mode
  json_flag: ""                 # the flag/param that forces structured output, if any
  common_fields: []
  error_handling: []

pitfalls: []
  # - "TODO: anything non-obvious that would trip up an agent using this tool"
'''

_API_TEMPLATE = '''# Tool Profile for __NAME__ — generated by `tool-enabler new`.
# Fill in every TODO below, then run `tool-enabler validate`. Passing
# validation only means the YAML is well-formed, not that the TODOs are
# filled in — that part is on you.
#
# Full schema reference: profiles/README.md in the tool-enabler repo.
# docs/custom-tools.md walks through a complete worked example.

name: __NAME__
display_name: "TODO: human-readable name, e.g. My Internal Service"
interface: api
category: ""                  # optional, free text

detect:
  auth_check: "TODO: a cheap curl call that confirms the auth handshake works"

api:
  base_url: "TODO: https://api.example.com"
  auth:
    type: "TODO: a label — bearer_token, basic_api_token, oauth2_client_credentials, api_key, ..."
    header: "TODO: e.g. Authorization: Bearer $MY_TOKEN"
    env_vars: []
      # - "MY_TOKEN"
    how_to_obtain: "TODO: where/how a human sets these credentials up once"
    session_setup: []
      # - "curl ... /oauth/token ..."   # only needed if auth is a multi-step handshake
    notes: ""              # token lifetime, revocation behavior, anything non-obvious
  rate_limits: ""           # optional

when_to_use:
  - "TODO: a concrete task this system covers"

prefer_over:
  - tool: "TODO: e.g. the system's web UI"
    reason: "TODO: why this is better for that"

capabilities:
  # Required: at least one entry.
  - task: "TODO: what this accomplishes"
    method: "GET"
    path: "TODO: /some/endpoint"
    command: 'curl -s -H "Authorization: Bearer $MY_TOKEN" "TODO: full URL"'
    notes: ""
    example_output: ""
    read_only: true

output_parsing:
  common_fields: []
  error_handling: []

pitfalls:
  - "curl does not fail non-zero on HTTP error responses by default — check the status code or response body, not the exit code."
'''


def render_new_profile(name: str, interface: str) -> str:
    template = _API_TEMPLATE if interface == "api" else _CLI_TEMPLATE
    return template.replace("__NAME__", name)
